async function ladeTermine() {
  const url =
    "/api/termine?klasse=2AHIF";
  const antwort = await fetch(url);
  if (!antwort.ok) {
    throw new Error(
      "HTTP " + antwort.status);
  }
  const termine =
    await antwort.json();

  const liste = document
    .querySelector("#termine");
  for (const t of termine) {
    const li =
      document.createElement("li");
    li.textContent =
      t.datum + ": " + t.titel;
    liste.append(li);
  }
}

ladeTermine().catch((fehler) => {
  console.log("Fehler:",
    fehler.message);
});

// Neuen Termin anlegen (POST)
async function speichere(termin) {
  const antwort = await fetch(
    "/api/termine", {
      method: "POST",
      headers: {"Content-Type":
        "application/json"},
      body: JSON.stringify(termin)
    });
  return antwort.status;
}

speichere({ titel: "Test POS",
  datum: "2026-11-27" })
  .then((s) => console.log(s));
// 201, wenn alles klappt

